using Race_Day_Part_3_MVC.Services;
using Microsoft.AspNetCore.Authentication.Cookies;

var builder = WebApplication.CreateBuilder(args);

// 1. Add standard Model-View-Controller system capabilities
builder.Services.AddControllersWithViews();

// 2. Add structural HttpContext capabilities for shared view pipelines
builder.Services.AddHttpContextAccessor();

// 3. Configure a bulletproof In-Memory Session management cookie loop
builder.Services.AddDistributedMemoryCache();
builder.Services.AddSession(options =>
{
    options.IdleTimeout = TimeSpan.FromMinutes(30);
    options.Cookie.HttpOnly = true;
    options.Cookie.IsEssential = true;
});

// 4. Configure standard Cookie Authentication Fallbacks to hold session state keys securely
builder.Services.AddAuthentication(CookieAuthenticationDefaults.AuthenticationScheme)
    .AddCookie(options =>
    {
        options.LoginPath = "/Account/Login";
        options.ExpireTimeSpan = TimeSpan.FromMinutes(30);
    });

// 5. CRITICAL INJECTION FIX: Links the IApiService interface cleanly to the ApiService engine class
builder.Services.AddHttpClient<IApiService, ApiService>();

var app = builder.Build();

if (!app.Environment.IsDevelopment())
{
    app.UseExceptionHandler("/Home/Error");
    app.UseHsts();
}

app.UseHttpsRedirection();
app.UseStaticFiles();

// CRITICAL PIPELINE ORDER: Governs application runtime task sequence matching
app.UseRouting();

app.UseSession();
app.UseAuthentication();
app.UseAuthorization();

// Setup the fallback default routing entry point matching your login controllers
app.MapControllerRoute(
    name: "default",
    pattern: "{controller=Account}/{action=Login}/{id?}");

app.Run();
